questionvariables.text:
var_list: [x, z, w, r, b, q, k,m,n];
/* Randomly select a variable from the list */
var: rand(var_list);
base:rand(10)+2; /*the base of the exponential*/
const:1; /*coefficent of x*/
point:0; /*limit point*/
y_cord:rand(4)+1;
fx:base^(var*const); /*the function*/
fxh:base^(var*const+h);
/* Define the function to compute the difference quotient */
num: fxh-fx; /*numerator*/
den:h; /*denominator*/
df:num/den;
df_point:at(df,[var=point]);
df_point_x:at(df_point,[h=var]);
num1:num(df_point_x);
den1:denom(df_point_x);
dnum:diff(num1,var); /*derivative of the numerator */
dden:diff(den1,var); /*derivative of the denominator */

ta:at(dnum, [var=point])/at(dden, [var=point]); /*Model answer*/
